BEGIN;
DELETE FROM historico; DELETE FROM recorrido_atracciones; DELETE FROM recorrido_zona; DELETE FROM recorrido; DELETE FROM atraccion; DELETE FROM zona; DELETE FROM estacion;
-- estaciones (4) --
-- zonas (19) --
-- atracciones: import a temp y mapeo clasificacion texto->ordinal enum --
CREATE TEMP TABLE atr_import (id_atraccion bigint, clasificacion text, descripcion text, foto_url text, geom_wkt text, nombre text) ON COMMIT DROP;
SELECT id_atraccion,
  CASE clasificacion
    WHEN 'CULTURAL' THEN 0 WHEN 'TEATRO' THEN 1 WHEN 'HISTORICA' THEN 2
    WHEN 'URBANA' THEN 3 WHEN 'GASTRONOMICO' THEN 4 WHEN 'PLAYA' THEN 5
    WHEN 'TERMAL' THEN 5 WHEN 'NATURAL' THEN 6 WHEN 'AVENTURA' THEN 6 WHEN 'RURAL' THEN 6
    ELSE 0 END,
  descripcion, foto_url, geom_wkt::geometry::geography, nombre
FROM atr_import;
-- recorridos (57) --
-- bump secuencias para que el ABM siga desde el max --
SELECT setval(pg_get_serial_sequence('atraccion','id_atraccion'), (SELECT MAX(id_atraccion) FROM atraccion));
SELECT setval(pg_get_serial_sequence('zona','id_zona'), (SELECT MAX(id_zona) FROM zona));
SELECT setval(pg_get_serial_sequence('recorrido','id_recorrido'), (SELECT MAX(id_recorrido) FROM recorrido));
SELECT setval(pg_get_serial_sequence('estacion','id_estacion'), (SELECT MAX(id_estacion) FROM estacion));
COMMIT;
